class RateLimiter {
    map<UserId, List<Timestamp>> slidingWindowMap;

    // Call this method whenever a request is made
    bool allow(UserId user, currentTime) {
        if !slidingWindowMap.containsKey(user) {
            slidingWindowMap.put(user, new List());
        }
        List<Timestamp> timestamps = slidingWindowMap.get(user);

        // Remove timestamps older than 60 seconds from the current request time
        while timestamps not empty and timestamps.first < currentTime - 60s {
            timestamps.removeFirst();
        }

        if timestamps.size < 5 {
            timestamps.addLast(currentTime);
            return true;   // request is allowed
        } else {
            return false;  // rate limit exceeded
        }
    }
}
```

This keeps a per‑user list of the timestamps of the last (up to) five requests and checks whether a new request would exceed the limit. Clean‑up of old entries is performed on each request, keeping memory usage bounded.

